1	import { load as yamlLoad } from "js-yaml";
2	
3	export type LogEntry = {
4	  action: string;
5	  by: string;
6	  at: string;
7	  note?: string;
8	};
9	
10	export type ParsedTask = {
11	  id: string;
12	  title: string;
13	  status: string;
14	  dependsOn: string[];
15	  description?: string;
16	  priority?: string;
17	  execution?: { actor_type: string; last_updated_by?: string; last_updated_at?: string };
18	  branch?: string;
19	  pr?: { url?: string; status?: string };
20	  workspace_pr?: { url?: string; status?: string };
21	  blockedReason?: string;
22	  blockedContext?: Record<string, unknown>;
23	  log?: LogEntry[];
24	};
25	
26	export type ParsedFeature = {
27	  id: string;
28	  title: string;
29	  featureStatus: string;
30	  tasks: ParsedTask[];
31	};
32	
33	type RawFeatureStatus = {
34	  feature_id?: string;
35	  title?: string;
36	  feature_status?: string;
37	  stage?: string;
38	};
39	
40	type RawTask = {
41	  id?: string;
42	  title?: string;
43	  status?: string;
44	  depends_on?: string[];
45	  description?: string;
46	  priority?: string;
47	  execution?: { actor_type?: string; last_updated_by?: string; last_updated_at?: string };
48	  branch?: string;
49	  pr?: { url?: string; status?: string };
50	  workspace_pr?: { url?: string; status?: string };
51	  blocked_reason?: string;
52	  blocked_context?: Record<string, unknown>;
53	  log?: Array<{ action?: string; by?: string; at?: string; note?: string }>;
54	};
55	
56	export function parseFeatureStatus(
57	  raw: string,
58	  featureId?: string,
59	): RawFeatureStatus {
60	  try {
61	    return (yamlLoad(raw) as RawFeatureStatus) ?? {};
62	  } catch (err) {
63	    const id = featureId ?? "<unknown>";
64	    console.warn(`[yaml-parser] Failed to parse status.yaml for ${id}:`, err);
65	    return {};
66	  }
67	}
68	
69	export function parseTaskYaml(id: string, raw: string): ParsedTask | null {
70	  let data: RawTask;
71	  try {
72	    data = (yamlLoad(raw) as RawTask) ?? {};
73	  } catch (err) {
74	    console.warn(`[yaml-parser] Failed to parse task YAML for ${id}:`, err);
75	    return null;
76	  }
77	
78	  if (!data || typeof data !== "object") {
79	    console.warn(`[yaml-parser] Malformed task YAML for ${id}: not an object`);
80	    return null;
81	  }
82	
83	  const log: LogEntry[] | undefined = Array.isArray(data.log)
84	    ? data.log
85	        .filter(
86	          (e) =>
87	            e &&
88	            typeof e.action === "string" &&
89	            typeof e.by === "string" &&
90	            typeof e.at === "string",
91	        )
92	        .map((e) => ({
93	          action: e.action as string,
94	          by: e.by as string,
95	          at: e.at as string,
96	          ...(e.note !== undefined ? { note: e.note } : {}),
97	        }))
98	    : undefined;
99	
100	  return {
101	    id: typeof data.id === "string" ? data.id : id,
