157	function findTaskLocationForPullRequest(
158	  pull: BoardPullRequest,
159	  locations: TaskLocation[],
160	): TaskLocation | null {
161	  const byBranch = locations.find((location) => {
162	    const task = location.task;
163	    return (
164	      task.branch === pull.headRef ||
165	      task.pr?.url === pull.htmlUrl ||
166	      task.workspace_pr?.url === pull.htmlUrl
167	    );
168	  });
169	  if (byBranch) return byBranch;
170	
171	  let taskId = extractTaskIdFromBranch(pull.headRef);
172	  if (!taskId) {
173	    const textToScan = `${pull.title ?? ""} ${pull.body ?? ""}`;
174	    const match = textToScan.match(/(?:^|[^a-z0-9])(T\d+)(?:\.yaml)?(?:$|[^a-z0-9])/i);
175	    if (match) {
