268	        .filter((file): file is PullRequestTaskFile => file !== null);
269	
270	      await Promise.all(
271	        taskFiles.map(async (taskFile) => {
272	          let raw: string;
273	          try {
274	            raw = await client.getFileContent(taskFile.path, {
275	              ref: pull.headRef,
276	            });
277	          } catch (err) {
278	            if (err instanceof GitHubNotFoundError) return;
279	            throw err;
280	          }
281	
282	          const branchTask = parseTaskYaml(taskFile.taskId, raw);
283	          if (!branchTask) return;
