294	async function applyMappedPullRequestTaskOverrides(
295	  client: BoardDataClient,
296	  features: ParsedFeature[],
297	  pulls: BoardPullRequest[],
298	): Promise<ParsedFeature[]> {
299	  const nextFeatures = features.map((feature) => ({
300	    ...feature,
301	    tasks: [...feature.tasks],
302	  }));
303	  const locations = buildTaskLocations(nextFeatures);
304	
305	  await Promise.all(
306	    pulls.map(async (pull) => {
307	      const location = findTaskLocationForPullRequest(pull, locations);
308	      if (!location) return;
309	
310	      let raw: string;
311	      try {
312	        raw = await client.getFileContent(location.path, {
313	          ref: pull.headRef,
314	        });
315	      } catch (err) {
316	        if (err instanceof GitHubNotFoundError) return;
317	        throw err;
318	      }
319	
320	      const branchTask = parseTaskYaml(location.task.id, raw);
321	      if (!branchTask) return;
322	
323	      nextFeatures[location.featureIndex].tasks[location.taskIndex] =
324	        mergePullRequestTask(location.task, branchTask, pull);
325	    }),
326	  );
327	
328	  return nextFeatures;
329	}
330	
331	async function applyOpenPullRequestTaskOverrides(
332	  client: BoardDataClient,
333	  features: ParsedFeature[],
334	): Promise<ParsedFeature[]> {
335	  if (!client.listOpenPullRequests) return features;
336	
337	  const pulls = await client.listOpenPullRequests();
338	  if (pulls.length === 0) return features;
339	
340	  if (client.listPullRequestFiles) {
341	    return applyPullRequestFileTaskOverrides(client, features, pulls);
342	  }
343	
344	  return applyMappedPullRequestTaskOverrides(client, features, pulls);
345	}
