347	export async function fetchBoardData(
348	  client: BoardDataClient,
349	): Promise<ParsedFeature[]> {
350	  let rootEntries: GitHubEntry[];
351	  try {
352	    rootEntries = await client.listDirectory(FEATURES_ROOT);
353	  } catch (err) {
354	    throw new BoardLoadFailure(mapClientError(err));
355	  }
356	
357	  const featureDirs = rootEntries.filter((entry) => entry.type === "dir");
358	
359	  let features: ParsedFeature[];
360	  try {
361	    features = await Promise.all(
362	      featureDirs.map((dir) => loadFeature(client, dir)),
363	    );
364	  } catch (err) {
365	    if (err instanceof BoardLoadFailure) throw err;
366	    throw new BoardLoadFailure(mapClientError(err));
367	  }
368	
369	  features.sort((a, b) => a.id.localeCompare(b.id));
370	  return features;
371	}
372	
373	export async function fetchPullRequestTaskData(
374	  client: BoardDataClient,
375	): Promise<ParsedFeature[]> {
376	  if (!client.listOpenPullRequests) return [];
377	
378	  let pulls: BoardPullRequest[];
379	  try {
380	    pulls = await client.listOpenPullRequests();
381	  } catch (err) {
382	    throw new BoardLoadFailure(mapClientError(err));
383	  }
384	
385	  if (pulls.length === 0) return [];
386	
387	  try {
388	    if (client.listPullRequestFiles) {
389	      const features = await applyPullRequestFileTaskOverrides(client, [], pulls);
390	      features.sort((a, b) => a.id.localeCompare(b.id));
391	      return features;
392	    }
393	
394	    // Fallback if listPullRequestFiles is not supported
395	    const rootEntries = await client.listDirectory(FEATURES_ROOT);
396	    const featureDirs = rootEntries.filter((entry) => entry.type === "dir");
397	    const baseFeatures = await Promise.all(
398	      featureDirs.map((dir) => loadFeature(client, dir)),
399	    );
400	    const features = await applyMappedPullRequestTaskOverrides(
401	      client,
402	      baseFeatures,
403	      pulls,
404	    );
405	    
406	    features.sort((a, b) => a.id.localeCompare(b.id));
407	    return features;
408	  } catch (err) {
409	    if (err instanceof BoardLoadFailure) throw err;
410	    throw new BoardLoadFailure(mapClientError(err));
411	  }
412	}
