13	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
14	import React from "react";
15	import { renderToStaticMarkup } from "react-dom/server";
16	
17	// ---------------------------------------------------------------------------
18	// Filter initialisation (round-trip: store → restore → default)
19	// ---------------------------------------------------------------------------
20	
21	const store: Record<string, string> = {};
22	const mockLS = {
23	  getItem: (key: string) => store[key] ?? null,
24	  setItem: (key: string, value: string) => {
25	    store[key] = value;
26	  },
27	  removeItem: (key: string) => {
28	    delete store[key];
29	  },
30	  clear: () => {
31	    for (const key of Object.keys(store)) delete store[key];
32	  },
33	};
34	
35	// @ts-expect-error test shim
36	global.window = {};
37	// @ts-expect-error test shim
38	global.localStorage = mockLS;
39	
40	import {
41	  getDefaultStatusFilter,
42	  getStoredStatusFilter,
43	  saveStatusFilter,
44	} from "../features/board/lib/status-filter-store";
45	
46	beforeEach(() => {
47	  mockLS.clear();
48	});
49	
50	describe("filter initialisation — first visit vs returning visit", () => {
51	  it("returns null when localStorage is empty (first visit)", () => {
52	    expect(getStoredStatusFilter()).toBeNull();
53	  });
54	
55	  it("default filter is all-except-done on first visit", () => {
56	    const filter = getStoredStatusFilter() ?? getDefaultStatusFilter();
57	    expect(filter).not.toContain("done");
58	    expect(filter.length).toBeGreaterThan(0);
59	  });
60	
61	  it("restores a previously saved filter on returning visit (includes done)", () => {
62	    saveStatusFilter(["todo", "done"]);
63	    const filter = getStoredStatusFilter() ?? getDefaultStatusFilter();
64	    expect(filter).toEqual(["todo", "done"]);
65	  });
66	
67	  it("returns default (not stored) when storage holds invalid data", () => {
68	    mockLS.setItem("dashboard:board-status-filter", '{"bad":"data"}');
69	    const filter = getStoredStatusFilter() ?? getDefaultStatusFilter();
70	    expect(filter).toEqual(getDefaultStatusFilter());
71	  });
72	
73	  it("persisted empty filter is restored as-is (user opted out of all filters)", () => {
74	    saveStatusFilter([]);
75	    const filter = getStoredStatusFilter() ?? getDefaultStatusFilter();
76	    expect(filter).toEqual([]);
77	  });
78	});
79	
